<!doctype html><html lang="en"><head><meta charset="UTF-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#26384b}.card{width:300px;border:1px solid #b7d7e0;border-radius:12px;text-align:center;padding:20px}.heading{background:#087cba;color:white;padding:12px}.photo{width:80px;height:80px;object-fit:cover;border-radius:40px}.initials{width:80px;height:80px;border-radius:40px;background:#eaf1ee;color:#438271;line-height:80px;font-size:25px;margin:15px auto}.qr{width:100px;height:100px}p{font-size:12px}</style></head><body><div class="card"><div class="heading">School Management System<br>STUDENT ID CARD</div>@if($photo)<p><img class="photo" src="{{ $photo }}" alt="Student photo"></p>@else<div class="initials">{{ mb_strtoupper(mb_substr($student->first_name,0,1).mb_substr($student->last_name ?? '',0,1)) }}</div>@endif<h2>{{ $student->first_name }} {{ $student->last_name }}</h2><p>{{ $options['class_id'][$student->class_id] ?? 'Class unassigned' }} / {{ $options['section_id'][$student->section_id] ?? 'Section unassigned' }}</p><p><strong>{{ $student->admission_no }}</strong></p><img class="qr" src="{{ $qr }}" alt="Student profile QR code"><p>Scan to open student profile</p></div></body></html>
